#include "phase-adaptive-prior.hpp"
namespace cm8 {
using namespace adaptive;
Point phi(Point q){if(q.infinity()||q.x==10)return {};I v=ipow(mod(q.x-10,13),11,13);return {mod(12*(q.x+2*v),13),mod(8*q.y*(1-2*v*v),13)};}
Json pj(Point q){return nums({q.x,q.y});}
Point inverse7(const Curve&e,Point P,Point q){for(I i=0;i<7;++i){auto p=e.scalar(i,P);if(phi(p)==q)return p;}throw std::runtime_error("no subgroup inverse");}
Json query(const Curve&c,Point R,const std::vector<Point>&base){
 require(!R.infinity(),"affine query");std::vector<I>xs{base[0].x,base[1].x};auto f=system_s3(c.a,c.b,R.x,13),h=remainder(c,R.x,xs),gx=base_poly(xs,0,13),gy=base_poly(xs,1,13);auto raw=solve({f,gx,gy},13),red=solve({h,gx,gy},13);require(dump(raw.at("roots"))==dump(red.at("roots")),"encoding roots");auto tested=arr(),lifts=arr(),rows=arr();std::set<std::vector<I>>rr;std::vector<Mono>actual;
 for(I i=0;i<2;++i)for(I j=0;j<2;++j){bool any=false;for(I si:{-1,1})for(I sj:{-1,1}){auto A=si<0?c.neg(base[i]):base[i],B=sj<0?c.neg(base[j]):base[j],sum=c.add(A,B);tested.items.push_back(obj({{"i",num(i)},{"j",num(j)},{"si",num(si)},{"sj",num(sj)},{"A",pj(A)},{"B",pj(B)},{"sum",pj(sum)},{"accepted",truth(sum==R)}}));if(sum==R){any=true;lifts.items.push_back(nums({i,j,si,sj}));std::vector<I>r(2);r[i]=mod(r[i]+si,7);r[j]=mod(r[j]+sj,7);rr.insert(r);}}if(any)actual.push_back({xs[i],xs[j]});}
 std::sort(actual.begin(),actual.end());auto aj=arr();for(auto xy:actual)aj.items.push_back(nums({xy[0],xy[1]}));require(dump(aj)==dump(red.at("roots")),"actual point lifting");for(auto&r:rr)rows.items.push_back(nums(r));return obj({{"target",pj(R)},{"original",raw},{"reduced",red},{"tested",tested},{"lifts",lifts},{"rows",rows}});
}
Json arm(const Curve&e,const Curve&c,Point P,Point G,const std::vector<Point>&base,bool mapped){
 auto bj=arr();for(auto B:base)bj.items.push_back(pj(B));auto targets=arr();Echelon rank(7),equations(7);auto setupq=arr();
 for(I n=1;n<7;++n){auto q=query(c,c.scalar(n,G),base);I before=I(rank.pivots.size());for(auto&r:q.at("rows").items){auto v=vec(r);rank.insert(v);if(equations.pivots.size()<2){v.push_back(n);equations.insert(v);}}q.fields["n"]=num(n);q.fields["before"]=num(before);q.fields["after"]=num(I(rank.pivots.size()));if(setupq.items.empty()||setupq.items.back().at("rank").integer()<2)setupq.items.push_back(obj({{"n",num(n)},{"query",q},{"rank",num(I(equations.pivots.size()))}}));targets.items.push_back(q);}
 require(equations.pivots.size()==2&&!equations.pivots.count(2),"base log setup");std::vector<I>logs(2);for(auto it=equations.pivots.rbegin();it!=equations.pivots.rend();++it){I j=it->first,v=it->second[2];for(I k=j+1;k<2;++k)v-=it->second[k]*logs[k];logs[j]=mod(v,7);}for(I i=0;i<2;++i)require(c.scalar(logs[i],G)==base[i],"base logs");
 auto recover=[&](Point Q){Point M=mapped?phi(Q):Q;I answer=-1;auto attempts=arr();for(I shift=0;shift<7&&answer<0;++shift){auto R=c.add(M,c.scalar(shift,G));if(R.infinity()){attempts.items.push_back(obj({{"shift",num(shift)},{"identity",truth()}}));continue;}auto q=query(c,R,base);q.fields["shift"]=num(shift);q.fields["identity"]=truth(false);if(!q.at("lifts").items.empty()){auto l=vec(q.at("lifts").items.front());answer=mod(l[2]*logs[l[0]]+l[3]*logs[l[1]]-shift,7);}attempts.items.push_back(q);}require(answer>=0&&e.scalar(answer,P)==Q,"source scalar");return obj({{"source",pj(Q)},{"mapped",pj(M)},{"answer",num(answer)},{"map_calls",num(mapped?1:0)},{"attempts",attempts}});};
 auto rec=arr();for(I n=1;n<7;++n)rec.items.push_back(recover(e.scalar(n,P)));return obj({{"generator",pj(G)},{"base_points",bj},{"targets",targets},{"setup_queries",setupq},{"base_logs",nums(logs)},{"recoveries",rec}});
}
}
int cm8_reference_main(int argc,char**argv){try{using namespace cm8;require(argc==3,"cm8-transfer ROOT FRESH_DIR");fs::path root=argv[1],out=argv[2];require(!fs::exists(out),"fresh output");fs::create_directories(out);Field k(13);Curve E(k,1,4),T(k,4,6);auto P=generator(E,7),U=phi(P);require(!U.infinity()&&T.scalar(7,U).infinity(),"image order");auto map=arr();I pairs=0;auto pts=E.points();require(pts.size()==14&&T.points().size()==14,"orders");for(auto A:pts){require(T.contains(phi(A)),"image curve");if(phi(A).infinity())require(A.infinity()||A==Point{10,0},"kernel");map.items.push_back(obj({{"source",pj(A)},{"image",pj(phi(A))}}));for(auto B:pts){require(phi(E.add(A,B))==T.add(phi(A),phi(B)),"full rational hom");++pairs;}}for(I n=0;n<7;++n)require(phi(E.scalar(n,P))==T.scalar(n,U),"scalar transport");for(I c=1;c<13;++c)require(!(ipow(c,4,13)==4&&ipow(c,6,13)==8),"scaling isomorphism");
 std::map<std::string,Json>arms;for(auto entry:{std::pair{"main",E},std::pair{"twist",T}}){auto G=std::string(entry.first)=="main"?P:U;auto xs=subgroup_xs(entry.second,G,7);require(xs.size()==3,"x classes");I index=0;for(I i=0;i<3;++i)for(I j=i+1;j<3;++j){auto bs=representatives(entry.second,{xs[i],xs[j]});auto name=std::string(entry.first)+std::to_string(index);arms[name]=cm8::arm(E,entry.second,P,G,bs,std::string(entry.first)=="twist");std::vector<Point>mapped;for(auto B:bs)mapped.push_back(std::string(entry.first)=="main"?phi(B):inverse7(E,P,B));auto other=std::string(entry.first)=="main"?"matched":"pullback";arms[std::string(other)+std::to_string(index)]=cm8::arm(E,std::string(entry.first)=="main"?T:E,P,std::string(entry.first)=="main"?U:P,mapped,std::string(entry.first)=="main");++index;}}
 auto compares=arr();I original=0,reduced=0;for(I i=0;i<3;++i)for(I j=0;j<3;++j)for(I n=0;n<6;++n){auto&a=arms.at("main"+std::to_string(i)).at("targets").items[n];auto&b=arms.at("twist"+std::to_string(j)).at("targets").items[n];auto x=obj({{"main",num(i)},{"twist",num(j)},{"n",num(n+1)},{"main_useful",num(a.at("after").integer()-a.at("before").integer())},{"twist_useful",num(b.at("after").integer()-b.at("before").integer())}});for(auto mode:{"original","reduced"}){bool joint=x.at("twist_useful").integer()>x.at("main_useful").integer()&&b.at(mode).at("matrix_degree").integer()<a.at(mode).at("matrix_degree").integer();x.fields[mode]=obj({{"main_degree",a.at(mode).at("matrix_degree")},{"twist_degree",b.at(mode).at("matrix_degree")},{"joint_gain",truth(joint)}});if(std::string(mode)=="original")original+=joint;else reduced+=joint;}compares.items.push_back(x);}
 for(I i=0;i<3;++i)for(auto pair:{std::pair{"main","matched"},std::pair{"twist","pullback"}})for(I n=0;n<6;++n){auto&a=arms.at(std::string(pair.first)+std::to_string(i)).at("targets").items[n];auto&b=arms.at(std::string(pair.second)+std::to_string(i)).at("targets").items[n];for(auto key:{"rows","lifts","before","after"})require(dump(a.at(key))==dump(b.at(key)),"matched rows");}
 auto pins=arr();for(auto&[name,a]:arms){auto bytes=dump(a)+'\n';std::ofstream(out/(name+".json"))<<bytes;pins.items.push_back(obj({{"name",str(name)},{"sha256",str(digest(bytes))}}));}
 const std::string s="research/quadratic_twist_evidence_20261021/";auto sources=arr();for(auto p:{s+"native/cm8-transfer.cpp",s+"CM8_TRANSFER_20261025_PROTOCOL.md",s+"native/phase-adaptive-prior.hpp",s+"native/reduced-s3-20261025/cases/p13-a1-b4-r7-size2-policy0.json",s+"native/adaptive-s3-20261025/cases/p13-a1-b4-r7-size2-policy0.json"})sources.items.push_back(obj({{"path",str(p)},{"sha256",str(digest(read(root/p)))}}));
 auto index=obj({{"schema",str("quadratic-twist-cm8-transfer/v1")},{"P",pj(P)},{"U",pj(U)},{"point_map",map},{"addition_pairs",num(pairs)},{"arms",pins},{"comparisons",compares},{"joint_original",num(original)},{"joint_reduced",num(reduced)},{"sources",sources}});std::ofstream(out/"index.json")<<dump(index)<<'\n';std::cout<<"12 arms /72 source recoveries; joint original="<<original<<" reduced="<<reduced<<"; "<<pairs<<" actual group pairs pass\n";
return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
